			q = c_surcharge * cpp.SysMath.Sqrt_d(h_orif)
			if (flap) {
				var a: Double = weirOpenArea!!.invoke(y_open)
				if (a > 0.0) {
					var v: Double = q / a
					var hloss: Double = (((4.0 / F_constants.GRAVITY) * v) * v) * cpp.SysMath.Exp_d(((-1.15) * v) / cpp.SysMath.Sqrt_d(y_open))
					h_orif -= hloss
					h_orif = cpp.M.max_d_d(h_orif, 0.0)
					q = c_surcharge * cpp.SysMath.Sqrt_d(h_orif)
				}
			}
			(links!!.depth)!!.a!![uj.toInt()] = y_open
			(links!!.dqdh)!!.a!![uj.toInt()] = if (h_orif > 0.0) q / (2.0 * h_orif) else 0.0
		} else {
			if (hgl1.v >= hcrown) {
				head = hcrown - hcrest
			}
			var q1: cpp.RefD.Cell = cpp.RefD.Cell(0.0)
			var q2: cpp.RefD.Cell = cpp.RefD.Cell(0.0)
			weirFlow!!.invoke(head, dir, q1, q2)
			if (flap) {
				var area: Double = weirOpenArea!!.invoke(head)
				if (area > 1E-06) {
					var veloc: Double = (q1.v + q2.v) / area
					var hLoss: Double = (((4.0 / F_constants.GRAVITY) * veloc) * veloc) * cpp.SysMath.Exp_d(((-1.15) * veloc) / cpp.SysMath.Sqrt_d(head))
					head = head - hLoss
					if (head < 0.0) {
						head = 0.0
					}
					weirFlow!!.invoke(head, dir, q1, q2)
				}
			}
			if (cpp.SysMath.Abs_d(head) >= FUDGE_W) {
				var q1h: Double = cpp.SysMath.Abs_d(q1.v / head)
				var q2h: Double = cpp.SysMath.Abs_d(q2.v / head)
				__sw7@ do {
					when (wt) {
						0 -> {
							(links!!.dqdh)!!.a!![uj.toInt()] = 1.5 * q1h
							break@__sw7
						}
						1 -> {
							(links!!.dqdh)!!.a!![uj.toInt()] = (if (dir < 0.0) 1.5 else 1.67) * q1h
							break@__sw7
						}
						2 -> {
							(links!!.dqdh)!!.a!![uj.toInt()] = if (q2h == 0.0) 2.5 * q1h else (1.5 * q1h) + (2.5 * q2h)
							break@__sw7
						}
						else -> {
							(links!!.dqdh)!!.a!![uj.toInt()] = (1.5 * q1h) + (2.5 * q2h)
							break@__sw7
						}
					}
				} while (false)
			} else {
				(links!!.dqdh)!!.a!![uj.toInt()] = 0.0
			}
			if (hgl2.v > hcrest) {
				if (!hydstruct_StructureSolver.S_weirPower_49_done) {
					hydstruct_StructureSolver.S_weirPower_49 = doubleArrayOf(1.5, 1.6666666666666667, 2.5, 1.5)
					hydstruct_StructureSolver.S_weirPower_49_done = true
				}
				var ratio: Double = (hgl2.v - hcrest) / (hgl1.v - hcrest)
				var wp: Double = if ((wt >= 0) && (wt < 4)) cpp.PtrD(hydstruct_StructureSolver.S_weirPower_49, 0L).get_Item_i(wt) as Double else 1.5
				q1.v *= cpp.SysMath.Pow_d(1.0 - cpp.SysMath.Pow_d(ratio, wp), 0.385)
				if (q2.v > 0.0) {
					q2.v *= cpp.SysMath.Pow_d(1.0 - cpp.SysMath.Pow_d(ratio, 2.5), 0.385)
				}
			}
			q = q1.v + q2.v
			(links!!.depth)!!.a!![uj.toInt()] = cpp.M.min_d_d(hgl1.v - hcrest, y_full)
		}
		if (q < 0.0) {
			q = 0.0
		}
		(links!!.flow)!!.a!![uj.toInt()] = q * dir
	}

	open fun computeOutletFlowK(ctx: SimulationContext?, k: Int) {
		var links: LinkData? = ctx!!.links
		var nodes: NodeData? = ctx!!.nodes
		var fu: Int = (ctx!!.options)!!.flow_units
		var unit_sys: Int = F_ucf.getUnitSystem(fu)
		var ucf_len: Double = cpp.PtrD((cpp.Ptr<DoubleArray?>(F_ucf.Ucf_UnitConversion, 0L)).get_Item_l(3L), 0L).get_Item_i(unit_sys) as Double
		var ucf_flow: Double = cpp.PtrD(F_ucf.Qcf_UnitConversion, 0L).get_Item_i(fu) as Double
		var FUDGE_OUT: Double = 0.0001
		var uk: Long = k.toLong()
		var j: Int = (this.outlets_!!.link_idx)!!.a!![uk.toInt()]
		var uj: Long = j.toLong()
		var n1: Int = (links!!.node1)!!.a!![uj.toInt()]
		var n2: Int = (links!!.node2)!!.a!![uj.toInt()]
		if ((n1 < 0) || (n2 < 0)) {
			(links!!.flow)!!.a!![uj.toInt()] = 0.0
			(links!!.depth)!!.a!![uj.toInt()] = 0.0
			return
		}
		var un1: Long = n1.toLong()
		var un2: Long = n2.toLong()
		if ((links!!.setting)!!.a!![uj.toInt()] == 0.0) {
			(links!!.flow)!!.a!![uj.toInt()] = 0.0
			return
		}
		var h1: cpp.RefD.Cell = cpp.RefD.Cell((nodes!!.depth)!!.a!![un1.toInt()] + (nodes!!.invert_elev)!!.a!![un1.toInt()])
		var h2: cpp.RefD.Cell = cpp.RefD.Cell(F_hydstruct.tailwaterHead_HydStructures(ctx, un1, un2))
		var dir: Int = if (h1.v >= h2.v) 1 else -1
		var y1: Double = (nodes!!.depth)!!.a!![un1.toInt()]
		if (dir < 0) {
			cpp.Std.swap__D(h1, h2)
			y1 = (nodes!!.depth)!!.a!![un2.toInt()]
		}
		var olr_c: Int = (ctx!!.link_subtypes)!!.outlet_row(j)
		var hcrest: Double = (nodes!!.invert_elev)!!.a!![un1.toInt()] + (if (olr_c >= 0) (((ctx!!.link_subtypes)!!.outlets)!!.crest_height)!!.a!![olr_c.toLong().toInt()] else 0.0)
		var outlet_type: Int = cpp.Conv.D2I((((ctx!!.link_subtypes)!!.outlets)!!.outlet_type)!!.a!![((ctx!!.link_subtypes)!!.outlet_row(j)).toLong().toInt()])
		var depth_based: Boolean = (outlet_type == 1) || (outlet_type == 3)
		var head: Double = if (depth_based) h1.v - hcrest else h1.v - cpp.M.max_d_d(h2.v, hcrest)
		var blocked_by_flap: Boolean = F_hydstruct.flapGateBlocks(ctx, j, n1, n2, dir.toDouble())
		if (((head <= FUDGE_OUT) || (y1 <= FUDGE_OUT)) || blocked_by_flap) {
			(links!!.flow)!!.a!![uj.toInt()] = 0.0
			(links!!.depth)!!.a!![uj.toInt()] = 0.0
			(links!!.flow_class)!!.a!![uj.toInt()] = FlowClass.DRY
			(links!!.dqdh)!!.a!![uj.toInt()] = 0.0
			return
		}
		var lookup_val: Double = head * ucf_len
		var q: Double = 0.0
		var ci: Int = (this.outlets_!!.curve_idx)!!.a!![uk.toInt()]
		if ((ci >= 0) && (java.lang.Long.compareUnsigned(ci.toLong(), ((ctx!!.tables)!!.tables)!!.size()) < 0)) {
			q = F_.table_lookup_cursor(((ctx!!.tables)!!.tables)!!.a!![ci.toLong().toInt()] as Table?, lookup_val)
			q /= ucf_flow
		} else {
			if (lookup_val > 0.0) {
				q = ((this.outlets_!!.q_coeff)!!.a!![uk.toInt()] * cpp.SysMath.Pow_d(lookup_val, (this.outlets_!!.q_expon)!!.a!![uk.toInt()])) / ucf_flow
			}
		}
		q *= (links!!.setting)!!.a!![uj.toInt()]
		if (q < 0.0) {
			q = 0.0
		}
		(links!!.flow)!!.a!![uj.toInt()] = q * dir.toDouble()
		(links!!.depth)!!.a!![uj.toInt()] = head
		(links!!.flow_class)!!.a!![uj.toInt()] = FlowClass.SUBCRITICAL
		(links!!.dqdh)!!.a!![uj.toInt()] = 0.0
	}

	open fun scatterOrificeSurfArea(ctx: SimulationContext?, node_new_surf_area: cpp.PtrD?, uk_: Long, uj_: Long, un1_: Long, un2_: Long) {
		if (cpp.PtrD.op_Eq(node_new_surf_area, cpp.PtrD.ZERO)) {
			return
		}
		var links: LinkData? = ctx!!.links
		var nodes: NodeData? = ctx!!.nodes
		var sa1: Double = (this.orifices_!!.surf_area)!!.a!![uk_.toInt()] * 0.5
		var sa2: Double = sa1
		var fc: Byte = (links!!.flow_class)!!.a!![uj_.toInt()]
		if ((fc == FlowClass.UP_CRITICAL) || ((nodes!!.type)!!.a!![un1_.toInt()] == NodeType.STORAGE)) {
			sa1 = 0.0
		}
		if ((fc == FlowClass.DN_CRITICAL) || ((nodes!!.type)!!.a!![un2_.toInt()] == NodeType.STORAGE)) {
			sa2 = 0.0
		}
		val __r1: cpp.RefD? = node_new_surf_area!!.ref_Item_ul(un1_)
		__r1!!.set(__r1!!.get() + sa1)
		val __r2: cpp.RefD? = node_new_surf_area!!.ref_Item_ul(un2_)
		__r2!!.set(__r2!!.get() + sa2)
	}

